-- 非递归vault的真实目录/对象控制事实，不随active替换。
CREATE TABLE vault_meta(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0));
INSERT INTO vault_meta(singleton,revision) VALUES(1,0);
CREATE TABLE backup_runs(backup_id TEXT PRIMARY KEY,source_epoch TEXT NOT NULL,barrier_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,manifest_hash TEXT NOT NULL DEFAULT '',manifest_json TEXT NOT NULL DEFAULT '',encrypted_manifest_ref TEXT NOT NULL DEFAULT '',key_id TEXT NOT NULL DEFAULT '',include_secrets INTEGER NOT NULL CHECK(include_secrets IN(0,1)),approved_by TEXT NOT NULL,approval_permission_revision INTEGER NOT NULL CHECK(approval_permission_revision>=0),approval_kind TEXT NOT NULL CHECK(approval_kind IN('manual','scheduled')),site_id TEXT NOT NULL,root_operation_id TEXT NOT NULL,input_hash TEXT NOT NULL,approved_at TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT,issues_json TEXT NOT NULL DEFAULT '[]');
CREATE INDEX backup_runs_order ON backup_runs(created_at DESC,backup_id DESC);
CREATE TABLE backup_objects(backup_id TEXT NOT NULL REFERENCES backup_runs(backup_id),owner TEXT NOT NULL,snapshot_id TEXT NOT NULL,schema_version INTEGER NOT NULL,watermark INTEGER NOT NULL,object_hash TEXT NOT NULL,encrypted_ref TEXT NOT NULL,snapshot_json TEXT NOT NULL,PRIMARY KEY(backup_id,owner));
CREATE TABLE stored_objects(object_id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,sha256 TEXT NOT NULL,byte_size INTEGER NOT NULL CHECK(byte_size>=0),relative_path TEXT NOT NULL UNIQUE,schema_version INTEGER NOT NULL,created_at TEXT NOT NULL);
